import type { CodegenConfig } from '@graphql-codegen/cli';

/**
 * Schema-first: SDL lives next to each module in typeDefs.ts (plucked via the GraphQL magic
 * comment) and resolver signatures are generated from it. `mappers` bind GraphQL types to the
 * internal domain models resolvers actually receive as `parent`.
 */
const config: CodegenConfig = {
  schema: ['src/graphql/typeDefs.ts', 'src/modules/*/typeDefs.ts'],
  generates: {
    'src/generated/graphql.ts': {
      plugins: [
        {
          add: {
            content:
              '/* eslint-disable */\n// Generated by graphql-codegen. Do not edit; run `npm run codegen`.',
          },
        },
        'typescript',
        'typescript-resolvers',
      ],
      config: {
        useTypeImports: true,
        useIndexSignature: false,
        enumsAsTypes: true,
        contextType: '../context.js#GraphQLContext',
        mappers: {
          Country: '../modules/country/model.js#CountryModel',
          Currency: '../modules/country/model.js#CurrencyModel',
          CountryConnection: '../modules/country/pagination.js#Connection<CountryModel>',
          Weather: '../modules/weather/model.js#WeatherReport',
          CurrentWeather: '../modules/weather/model.js#CurrentWeatherModel',
          DailyForecast: '../modules/weather/model.js#DailyForecastModel',
          DestinationScore: '../modules/trip/service.js#DestinationScoreModel',
          TripComparison: '../modules/trip/service.js#TripComparisonModel',
        },
        scalars: {},
      },
    },
  },
};

export default config;
